import 'package:flutter/material.dart';
import '../models/report.dart'; import '../services/report_service.dart'; import '../widgets/report_card.dart'; import 'report_details_screen.dart';
class ReportHistoryScreen extends StatefulWidget { const ReportHistoryScreen({super.key}); @override State<ReportHistoryScreen> createState()=>_ReportHistoryScreenState(); }
class _ReportHistoryScreenState extends State<ReportHistoryScreen>{late Future<List<IncidentReport>> reports; @override void initState(){super.initState();reports=ReportService().mine();} @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('My Reports')),body:FutureBuilder<List<IncidentReport>>(future:reports,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return const Center(child:Text('Unable to load reports. Check your connection.'));if(s.data!.isEmpty)return const Center(child:Text('No reports submitted yet.'));return RefreshIndicator(onRefresh:()async=>setState(()=>reports=ReportService().mine()),child:ListView(padding:const EdgeInsets.all(12),children:s.data!.map((r)=>ReportCard(report:r,onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ReportDetailsScreen(report:r)))).toList()));}));}
